import express from 'express';
import crypto from 'crypto';
import db from '../db.js';
import { requirePerm, logActivity } from '../auth.js';

const router = express.Router();
const I18N = { en:{joined:'Joined', eta:'ETA', surge:'Surge', voice:'Voice alert', think:'intake'}, hi:{joined:'शामिल', eta:'अनुमानित', surge:'भीड़', voice:'आवाज़ अलर्ट', think:'प्रवेश'}, ja:{joined:'受付', eta:'目安', surge:'混雑', voice:'音声通知', think:'受付中'} };
const DAY = 86_400_000;
const code = prefix => `${prefix}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
const isoDate = ts => new Date(ts).toISOString().slice(0, 10);
const dateStart = date => { const d = /^\d{4}-\d{2}-\d{2}$/.test(date || '') ? new Date(`${date}T00:00:00.000Z`) : new Date(); return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); };
const actor = req => req.user?.username || req.user?.role || 'system';
const publicRequests = new Map();
function publicRateLimit(req, res, next) {
  const key = req.ip || req.socket?.remoteAddress || 'unknown', now = Date.now();
  const recent = (publicRequests.get(key) || []).filter(t => now - t < 60_000);
  if (recent.length >= Number(process.env.HOSPITAL_PUBLIC_RATE_LIMIT || 20)) return res.status(429).json({ error: 'Too many requests. Please wait a minute and try again.' });
  recent.push(now); publicRequests.set(key, recent); next();
}
function detectLocale(t) { if (/[぀-ヿ]/.test(t || '')) return 'ja'; if (/[ऀ-ॿ]/.test(t || '')) return 'hi'; return 'en'; }
function understand(t) { const l = (t || '').toLowerCase(), m = l.match(/name is ([a-z]+)|i am ([a-z]+)|मेरा नाम ([a-z]+)|नाम ([a-z]+)|名前は ([a-z]+)|わたしは ([a-z]+)/) || []; const raw = m[1] || m[2] || m[3] || m[4] || m[5] || m[6]; return { name: raw ? raw.charAt(0).toUpperCase() + raw.slice(1) : '', complaint: (l.match(/fever|pain|दर्द|बुखार|熱|head|सिर|chest|सीने|頭|胸/) || [])[0] || '' }; }
function event(id, type, from, to, who = 'system', note = '') { db.prepare('INSERT INTO hospital_queue_events (appointment_id,event_type,from_status,to_status,actor,note,created_at) VALUES (?,?,?,?,?,?,?)').run(id, type, from || null, to || null, who, note, Date.now()); }
async function deliverNotification(row, appointment) {
  if (process.env.HOSPITAL_NOTIFICATION_TRANSPORT === 'mock' || process.env.AGENT_TEST_MODE === '1') return 'mock';
  const webhook = process.env.HOSPITAL_NOTIFICATION_WEBHOOK;
  if (!webhook) throw new Error('No notification provider configured');
  const response = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json', ...(process.env.HOSPITAL_NOTIFICATION_TOKEN ? { Authorization: `Bearer ${process.env.HOSPITAL_NOTIFICATION_TOKEN}` } : {}) }, body: JSON.stringify({ channel: row.channel, kind: row.kind, body: row.body, to: row.channel === 'email' ? appointment.email : appointment.phone, bookingCode: appointment.booking_code }) });
  if (!response.ok) throw new Error(`Provider returned ${response.status}`);
  return 'delivered';
}
function notify(id, kind, body, preferredChannel = '') {
  const appointment = db.prepare('SELECT * FROM hospital_appointments WHERE id=?').get(id); if (!appointment) return;
  const channel = preferredChannel || (appointment.phone ? 'sms' : appointment.email ? 'email' : 'in_app');
  const inserted = db.prepare('INSERT INTO hospital_notifications (appointment_id,channel,kind,body,status,created_at) VALUES (?,?,?,?,?,?)').run(id, channel, kind, body, 'queued', Date.now());
  const row = db.prepare('SELECT * FROM hospital_notifications WHERE id=?').get(inserted.lastInsertRowid);
  deliverNotification(row, appointment).then(() => db.prepare("UPDATE hospital_notifications SET status='delivered' WHERE id=?").run(row.id)).catch(error => db.prepare("UPDATE hospital_notifications SET status=? WHERE id=?").run(`failed: ${String(error.message).slice(0,100)}`, row.id));
}

function seedScheduling() {
  if (process.env.HOSPITAL_DEMO_SEED !== '1' || db.prepare('SELECT COUNT(*) c FROM hospital_doctors').get().c) return;
  const now = Date.now(), addDepartment = db.prepare('INSERT OR IGNORE INTO hospital_departments (name,location,created_at) VALUES (?,?,?)');
  [['General OPD','Main OPD'],['Pediatrics','Children’s Wing'],['Cardiology','Heart Centre']].forEach(row => addDepartment.run(...row, now));
  const add = db.prepare('INSERT INTO hospital_doctors (name,specialty,location,department,department_id,room,default_duration_min,created_at) VALUES (?,?,?,?,?,?,?,?)');
  [['Dr. Asha Mehta','General Medicine','Main OPD','General OPD','Room 101',15],['Dr. Rohan Shah','Pediatrics','Children’s Wing','Pediatrics','Room 202',20],['Dr. Neha Iyer','Cardiology','Heart Centre','Cardiology','Room 305',20]].forEach(([name,specialty,location,department,room,duration]) => {
    const departmentId = db.prepare('SELECT id FROM hospital_departments WHERE name=?').get(department).id;
    const doctorId = add.run(name,specialty,location,department,departmentId,room,duration,now).lastInsertRowid;
    for (let weekday = 0; weekday < 7; weekday++) db.prepare('INSERT INTO hospital_slot_policies (doctor_id,weekday,start_time,end_time,duration_min,capacity,service_type,created_at) VALUES (?,?,?,?,?,?,?,?)').run(doctorId,weekday,'09:00','17:00',duration,1,'Consultation',now);
  });
}
function ensureSlots(date, doctorId) {
  const start = dateStart(date), doctors = doctorId ? db.prepare('SELECT * FROM hospital_doctors WHERE id=? AND active=1').all(doctorId) : db.prepare('SELECT * FROM hospital_doctors WHERE active=1').all();
  if (db.prepare('SELECT 1 FROM hospital_holidays WHERE holiday_date=?').get(isoDate(start))) return;
  const add = db.prepare('INSERT OR IGNORE INTO hospital_slots (doctor_id,starts_at,ends_at,capacity,reserved,status,service_type,created_at) VALUES (?,?,?,?,?,?,?,?)');
  const weekday = new Date(start).getUTCDay();
  for (const doctor of doctors) {
    const policies = db.prepare('SELECT * FROM hospital_slot_policies WHERE doctor_id=? AND weekday=? AND active=1 ORDER BY start_time').all(doctor.id, weekday);
    for (const policy of policies) {
      const [startHour, startMinute] = policy.start_time.split(':').map(Number), [endHour, endMinute] = policy.end_time.split(':').map(Number), first = startHour * 60 + startMinute, last = endHour * 60 + endMinute;
      for (let minute = first; minute + policy.duration_min <= last; minute += policy.duration_min) { const starts = start + minute * 60_000, ends = starts + policy.duration_min * 60_000; const blocked = db.prepare("SELECT 1 FROM hospital_schedule_blocks WHERE doctor_id=? AND starts_at<? AND ends_at>? LIMIT 1").get(doctor.id, ends, starts); if (!blocked) add.run(doctor.id, starts, ends, policy.capacity, 0, 'open', policy.service_type, Date.now()); }
    }
  }
}
function recomputeQueue(doctorId, date) {
  const start = dateStart(date), end = start + DAY;
  const rows = db.prepare("SELECT id FROM hospital_appointments WHERE doctor_id=? AND checked_in_at>=? AND checked_in_at<? AND status IN ('checked_in','called') ORDER BY CASE priority WHEN 'urgent' THEN 0 ELSE 1 END, checked_in_at,id").all(doctorId, start, end);
  const historical = db.prepare("SELECT AVG(completed_at-called_at)/60000 avg FROM hospital_appointments WHERE doctor_id=? AND completed_at IS NOT NULL AND called_at IS NOT NULL AND completed_at>called_at").get(doctorId).avg;
  const serviceMinutes = Math.max(5, Math.min(60, Math.round(historical || db.prepare('SELECT default_duration_min duration FROM hospital_doctors WHERE id=?').get(doctorId)?.duration || 12)));
  const update = db.prepare('UPDATE hospital_appointments SET queue_number=?,estimated_wait_min=?,updated_at=? WHERE id=?'); rows.forEach((row, i) => update.run(i + 1, i * serviceMinutes, Date.now(), row.id));
}
function appointmentRow(id) { return db.prepare('SELECT a.*,d.name doctor_name,d.specialty,d.location,d.room,s.starts_at,s.ends_at,s.service_type FROM hospital_appointments a JOIN hospital_doctors d ON d.id=a.doctor_id LEFT JOIN hospital_slots s ON s.id=a.slot_id WHERE a.id=?').get(id); }
function publicAppointment(a) { if (!a) return null; const { abha_number, consent_at, priority_reason, ...safe } = a; return safe; }
function bookingPreview(a) { return a ? { booking_code:a.booking_code,status:a.status,doctor_name:a.doctor_name,specialty:a.specialty,location:a.location,room:a.room,starts_at:a.starts_at,ends_at:a.ends_at,service_type:a.service_type } : null; }
function portalAccess(req, appointment) {
  const token = String(req.get('x-patient-token') || '');
  const digest = token ? crypto.createHash('sha256').update(token).digest('hex') : '';
  return !!token && !!db.prepare("SELECT 1 FROM hospital_public_tokens WHERE appointment_id=? AND purpose='portal' AND code=? AND verified_at IS NOT NULL AND expires_at>?").get(appointment.id, digest, Date.now());
}
function portalBundle(appointment) {
  const related = db.prepare("SELECT a.id,a.booking_code,a.status,a.consultation_mode,a.payment_status,d.name doctor_name,d.specialty,d.location,d.room,s.starts_at,s.ends_at FROM hospital_appointments a JOIN hospital_doctors d ON d.id=a.doctor_id LEFT JOIN hospital_slots s ON s.id=a.slot_id WHERE (a.phone<>'' AND a.phone=?) OR a.id=? ORDER BY COALESCE(s.starts_at,a.created_at) DESC LIMIT 20").all(appointment.phone || '__none__', appointment.id);
  return {
    appointment: publicAppointment(appointment),
    appointments: related,
    notifications: db.prepare('SELECT channel,kind,body,status,created_at FROM hospital_notifications WHERE appointment_id=? ORDER BY created_at DESC LIMIT 30').all(appointment.id),
    documents: db.prepare('SELECT id,name,document_type,status,created_at FROM hospital_patient_documents WHERE appointment_id=? ORDER BY created_at DESC').all(appointment.id),
    stages: ['checked_in','called','completed'].includes(appointment.status) ? visitStages(appointment.id) : []
  };
}
const TRIAGE_FLAGS = ['difficulty_breathing','chest_pain','severe_bleeding','loss_of_consciousness','stroke_signs','self_harm_risk'];
const VISIT_STAGES = [['registration','Registration'],['vitals','Vitals'],['consultation','Consultation'],['lab','Laboratory'],['pharmacy','Pharmacy'],['billing','Billing']];
function ensureVisitStages(appointmentId) { const add = db.prepare('INSERT OR IGNORE INTO hospital_visit_stages (appointment_id,stage,label,status,updated_at) VALUES (?,?,?,?,?)'); for (const [stage,label] of VISIT_STAGES) add.run(appointmentId,stage,label,['lab','pharmacy','billing'].includes(stage) ? 'not_required' : 'waiting',Date.now()); }
function visitStages(appointmentId) { ensureVisitStages(appointmentId); return db.prepare('SELECT * FROM hospital_visit_stages WHERE appointment_id=? ORDER BY id').all(appointmentId); }
function fhirAppointment(a) { return { resourceType:'Appointment', id:String(a.id), identifier:[{system:'urn:masystem:booking',value:a.booking_code}], status: ({confirmed:'booked',checked_in:'arrived',called:'arrived',completed:'fulfilled',cancelled:'cancelled',no_show:'noshow',waitlisted:'waitlist'})[a.status] || 'pending', serviceType:a.service_type ? [{text:a.service_type}] : undefined, specialty:[{text:a.specialty}], description:a.reason || undefined, start:a.starts_at ? new Date(a.starts_at).toISOString() : undefined, end:a.ends_at ? new Date(a.ends_at).toISOString() : undefined, participant:[{actor:{display:a.patient_name},status:'accepted'},{actor:{display:a.doctor_name},status:'accepted'},{actor:{display:a.room || a.location},status:'accepted'}] }; }
async function syncIntegration(appointment, target) { const webhook = target === 'abdm' ? process.env.HOSPITAL_ABDM_WEBHOOK : process.env.HOSPITAL_HMIS_WEBHOOK, token = target === 'abdm' ? process.env.HOSPITAL_ABDM_TOKEN : process.env.HOSPITAL_HMIS_TOKEN; if (!webhook) throw new Error(`${target.toUpperCase()} integration is not configured.`); const response = await fetch(webhook,{method:'POST',headers:{'Content-Type':'application/fhir+json',...(token ? {Authorization:`Bearer ${token}`} : {})},body:JSON.stringify(fhirAppointment(appointment))}); if (!response.ok) throw new Error(`${target.toUpperCase()} returned ${response.status}`); }
function rebookAffectedAppointments(absence) {
  const rows = db.prepare("SELECT a.*,s.starts_at FROM hospital_appointments a JOIN hospital_slots s ON s.id=a.slot_id WHERE a.doctor_id=? AND a.status='confirmed' AND s.starts_at>=? AND s.starts_at<?").all(absence.doctor_id,absence.starts_at,absence.ends_at); let transferred = 0, needsRebooking = 0;
  for (const a of rows) { let replacement = null; if (absence.substitute_doctor_id) { ensureSlots(isoDate(a.starts_at),absence.substitute_doctor_id); replacement = db.prepare("SELECT * FROM hospital_slots WHERE doctor_id=? AND starts_at>=? AND starts_at<? AND status='open' AND reserved<capacity ORDER BY starts_at LIMIT 1").get(absence.substitute_doctor_id,a.starts_at,dateStart(isoDate(a.starts_at))+DAY); }
    if (replacement) { db.prepare('UPDATE hospital_slots SET reserved=MAX(reserved-1,0) WHERE id=?').run(a.slot_id); db.prepare('UPDATE hospital_slots SET reserved=reserved+1 WHERE id=?').run(replacement.id); db.prepare('UPDATE hospital_appointments SET doctor_id=?,slot_id=?,original_doctor_id=COALESCE(original_doctor_id,?),updated_at=? WHERE id=?').run(absence.substitute_doctor_id,replacement.id,absence.doctor_id,Date.now(),a.id); event(a.id,'substitute_rebooked','confirmed','confirmed','system',`Doctor absence ${absence.id}`); notify(a.id,'rebooked_substitute','Your appointment has been moved to an available substitute doctor and time.'); transferred++; }
    else { db.prepare("UPDATE hospital_appointments SET status='rebooking_required',original_doctor_id=COALESCE(original_doctor_id,?),updated_at=? WHERE id=?").run(absence.doctor_id,Date.now(),a.id); db.prepare('UPDATE hospital_slots SET reserved=MAX(reserved-1,0) WHERE id=?').run(a.slot_id); event(a.id,'rebooking_required','confirmed','rebooking_required','system',`Doctor absence ${absence.id}`); notify(a.id,'rebooking_required','Your doctor is unavailable. Our team will contact you with new appointment options.'); needsRebooking++; }
  } return { affected:rows.length,transferred,needsRebooking };
}
function promoteWaitlist(slotId) {
  const waiting = db.prepare("SELECT a.* FROM hospital_waitlist w JOIN hospital_appointments a ON a.id=w.appointment_id WHERE w.active=1 AND a.slot_id=? AND a.status='waitlisted' ORDER BY w.created_at LIMIT 1").get(slotId);
  if (!waiting) return;
  const now = Date.now(); db.prepare("UPDATE hospital_waitlist SET active=0 WHERE appointment_id=?").run(waiting.id); db.prepare("UPDATE hospital_slots SET reserved=reserved+1 WHERE id=?").run(slotId); db.prepare("UPDATE hospital_appointments SET status='confirmed',updated_at=? WHERE id=?").run(now, waiting.id);
  event(waiting.id,'waitlist_promoted','waitlisted','confirmed','system'); notify(waiting.id,'waitlist_promoted','A slot is now available and your appointment is confirmed.');
}

async function intake(text, locale) {
  locale = locale || detectLocale(text); const L = I18N[locale] || I18N.en, p = understand(text), waiting = db.prepare("SELECT COUNT(*) c FROM hospital_queue WHERE status='waiting'").get().c + 1, eta = waiting * 7;
  const id = db.prepare('INSERT INTO hospital_queue (name,complaint,locale,channel,position,eta_min,status,created_at) VALUES (?,?,?,?,?,?,?,?)').run(p.name || 'Guest', p.complaint, locale, 'web', waiting, eta, 'waiting', Date.now()).lastInsertRowid;
  const steps = [{tool:'think',result:`(${L.think}) ${p.name || 'Guest'}`},{tool:'join',result:`${L.joined} #${id} (web)`},{tool:'report_position',result:`${waiting}/${waiting} · ${eta} ${L.eta}`}];
  if (waiting >= 5) steps.push({tool:'surge_detected',result:`${L.surge}: ${waiting}`},{tool:'notify_voice',result:`${L.voice} (${waiting})`}); return { id, steps, locale };
}

