router.use('/public', publicRateLimit);
router.get('/public/doctors', (_req,res) => { seedScheduling(); res.json(db.prepare('SELECT id,name,specialty,location,department,room,default_duration_min FROM hospital_doctors WHERE active=1 ORDER BY name').all()); });
router.get('/public/services', (_req,res) => { seedScheduling(); res.json({departments:db.prepare('SELECT id,name,location FROM hospital_departments WHERE active=1 ORDER BY name').all(),doctors:db.prepare('SELECT id,name,specialty,location,department,room FROM hospital_doctors WHERE active=1 ORDER BY department,name').all()}); });
router.get('/public/slots', (req,res) => { const doctorId = Number(req.query.doctorId), date = String(req.query.date || isoDate(Date.now())); if (!doctorId) return res.status(400).json({error:'doctorId required'}); if (dateStart(date) < dateStart(isoDate(Date.now()))) return res.status(400).json({error:'Choose today or a future date.'}); seedScheduling(); ensureSlots(date, doctorId); const start = dateStart(date); res.json(db.prepare("SELECT id,starts_at,ends_at,capacity,reserved,status,service_type,(capacity-reserved) available FROM hospital_slots WHERE doctor_id=? AND starts_at>=? AND starts_at<? AND status='open' ORDER BY starts_at").all(doctorId, start, start + DAY)); });
router.post('/public/bookings', (req,res) => {
  const b = req.body || {}, name = String(b.patientName || '').trim().slice(0,100), doctorId = Number(b.doctorId), slotId = Number(b.slotId); if (!name || !doctorId || !slotId) return res.status(400).json({error:'patient name, doctor, and slot are required'});
  try {
    const result = db.transaction(() => { const slot = db.prepare('SELECT * FROM hospital_slots WHERE id=? AND doctor_id=?').get(slotId, doctorId); if (!slot) throw new Error('Selected slot is no longer available.'); const now = Date.now(), status = slot.reserved < slot.capacity ? 'confirmed' : b.joinWaitlist ? 'waitlisted' : ''; if (!status) throw new Error('This slot is full. Join the waitlist or choose another time.'); const mode = ['in_person','video'].includes(b.consultationMode) ? b.consultationMode : 'in_person', telehealth = mode === 'video' ? `${process.env.HOSPITAL_TELEHEALTH_BASE_URL || 'https://video.example.invalid/visit'}/${code('ROOM')}` : ''; const id = db.prepare('INSERT INTO hospital_appointments (booking_code,checkin_code,patient_name,phone,email,abha_number,consent_at,doctor_id,slot_id,reason,status,preferred_channel,caregiver_name,caregiver_phone,accessibility_needs,insurance_provider,insurance_member_id,consultation_mode,language,telehealth_url,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(code('APT'), code('CHK'), name, String(b.phone || '').slice(0,40), String(b.email || '').slice(0,254), String(b.abhaNumber || '').slice(0,30), b.consent ? now : null, doctorId, slotId, String(b.reason || '').slice(0,500), status, ['sms','email','whatsapp'].includes(b.preferredChannel) ? b.preferredChannel : 'sms', String(b.caregiverName || '').slice(0,100), String(b.caregiverPhone || '').slice(0,40), String(b.accessibilityNeeds || '').slice(0,500), String(b.insuranceProvider || '').slice(0,100), String(b.insuranceMemberId || '').slice(0,100), mode, String(b.language || 'en').slice(0,10), telehealth, now, now).lastInsertRowid; if (status === 'confirmed') db.prepare('UPDATE hospital_slots SET reserved=reserved+1 WHERE id=?').run(slotId); else db.prepare('INSERT INTO hospital_waitlist (appointment_id,requested_date,created_at) VALUES (?,?,?)').run(id, isoDate(slot.starts_at), now); event(id,status === 'confirmed' ? 'booked':'waitlisted',null,status,'patient'); notify(id,status === 'confirmed' ? 'booking_confirmation':'waitlist_confirmation',status === 'confirmed' ? 'Your appointment is confirmed.':'You are on the waitlist.', ['sms','email'].includes(b.preferredChannel) ? b.preferredChannel : ''); return appointmentRow(id); })();
    res.status(201).json({appointment:publicAppointment(result),checkinUrl:`/hospital/check-in?code=${result.checkin_code}`,manageUrl:`/hospital/visit?code=${result.booking_code}`});
  } catch (error) { res.status(409).json({error:error.message}); }
});
router.get('/public/bookings/:code', (req,res) => { const a = appointmentRowByBooking(req.params.code); if (!a) return res.status(404).json({error:'Booking not found.'}); res.json({appointment:bookingPreview(a),verificationRequired:true}); });
function appointmentRowByBooking(bookingCode) { return db.prepare('SELECT a.*,d.name doctor_name,d.specialty,d.location,d.room,s.starts_at,s.ends_at,s.service_type FROM hospital_appointments a JOIN hospital_doctors d ON d.id=a.doctor_id LEFT JOIN hospital_slots s ON s.id=a.slot_id WHERE a.booking_code=?').get(bookingCode); }
router.post('/public/bookings/:code/send-verification', (req,res) => {
  const a = appointmentRowByBooking(req.params.code); if (!a || (!a.phone && !a.email)) return res.status(404).json({error:'A booking with a phone or email is required.'});
  const otp = process.env.AGENT_TEST_MODE === '1' ? String(process.env.HOSPITAL_TEST_OTP || '123456') : String(Math.floor(100000 + Math.random() * 900000)), now = Date.now();
  db.prepare("UPDATE hospital_public_tokens SET expires_at=? WHERE appointment_id=? AND purpose='manage' AND verified_at IS NULL").run(now, a.id);
  db.prepare('INSERT INTO hospital_public_tokens (appointment_id,purpose,code,expires_at,created_at) VALUES (?,?,?,?,?)').run(a.id,'manage',otp,now + 10 * 60_000,now);
  notify(a.id,'verification_code',`Your MASystem Hospital verification code is ${otp}. It expires in 10 minutes.`);
  res.json({ok:true,delivery: process.env.HOSPITAL_NOTIFICATION_TRANSPORT === 'mock' || process.env.AGENT_TEST_MODE === '1' ? 'mock' : 'queued',...(process.env.AGENT_TEST_MODE === '1' ? {testCode:otp} : {})});
});
router.post('/public/bookings/:code/verify', (req,res) => { const a = appointmentRowByBooking(req.params.code), otp = String(req.body?.code || ''); if (!a) return res.status(404).json({error:'Booking not found.'}); const token = db.prepare("SELECT * FROM hospital_public_tokens WHERE appointment_id=? AND purpose='manage' AND code=? AND expires_at>? ORDER BY id DESC LIMIT 1").get(a.id,otp,Date.now()); if (!token) return res.status(400).json({error:'Invalid or expired verification code.'}); const now = Date.now(), session = crypto.randomBytes(24).toString('hex'), digest = crypto.createHash('sha256').update(session).digest('hex'); db.prepare('UPDATE hospital_public_tokens SET verified_at=? WHERE id=?').run(now,token.id); db.prepare("UPDATE hospital_public_tokens SET expires_at=? WHERE appointment_id=? AND purpose='portal'").run(now,a.id); db.prepare('INSERT INTO hospital_public_tokens (appointment_id,purpose,code,expires_at,verified_at,created_at) VALUES (?,?,?,?,?,?)').run(a.id,'portal',digest,now + 30 * 60_000,now,now); res.json({ok:true,patientToken:session,expiresIn:1800}); });
router.get('/public/portal/:code', (req,res) => { const a = appointmentRowByBooking(req.params.code); if (!a || !portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); res.json(portalBundle(a)); });
router.patch('/public/portal/:code/preferences', (req,res) => { const a = appointmentRowByBooking(req.params.code); if (!a || !portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); const b=req.body||{}, channel=['sms','email','whatsapp'].includes(b.preferredChannel)?b.preferredChannel:a.preferred_channel, language=String(b.language||a.language).slice(0,10); db.prepare('UPDATE hospital_appointments SET preferred_channel=?,language=?,caregiver_name=?,caregiver_phone=?,accessibility_needs=?,updated_at=? WHERE id=?').run(channel,language,String(b.caregiverName??a.caregiver_name).slice(0,100),String(b.caregiverPhone??a.caregiver_phone).slice(0,40),String(b.accessibilityNeeds??a.accessibility_needs).slice(0,500),Date.now(),a.id); event(a.id,'preferences_updated',a.preferred_channel,channel,'patient'); res.json(portalBundle(appointmentRow(a.id))); });
router.post('/public/portal/:code/previsit', (req,res) => { const a=appointmentRowByBooking(req.params.code); if(!a||!portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); const answers={medications:String(req.body?.medications||'').slice(0,1000),allergies:String(req.body?.allergies||'').slice(0,1000),notes:String(req.body?.notes||'').slice(0,1000)}; db.prepare('UPDATE hospital_appointments SET previsit_answers=?,updated_at=? WHERE id=?').run(JSON.stringify(answers),Date.now(),a.id); event(a.id,'previsit_completed',null,'completed','patient'); notify(a.id,'previsit_received','Your pre-visit information was received.'); res.json({ok:true,answers}); });
router.post('/public/portal/:code/documents', (req,res) => { const a=appointmentRowByBooking(req.params.code); if(!a||!portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); const name=String(req.body?.name||'').trim().slice(0,150), type=String(req.body?.documentType||'other').slice(0,50); if(!name)return res.status(400).json({error:'Document name is required.'}); const id=db.prepare('INSERT INTO hospital_patient_documents (appointment_id,name,document_type,created_at) VALUES (?,?,?,?)').run(a.id,name,type,Date.now()).lastInsertRowid; event(a.id,'document_received',null,'received','patient',type); res.status(201).json({document:db.prepare('SELECT id,name,document_type,status,created_at FROM hospital_patient_documents WHERE id=?').get(id)}); });
router.post('/public/portal/:code/payment-intent', (req,res) => { const a=appointmentRowByBooking(req.params.code); if(!a||!portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); if(!process.env.HOSPITAL_PAYMENT_WEBHOOK){db.prepare("UPDATE hospital_appointments SET payment_status='provider_required',updated_at=? WHERE id=?").run(Date.now(),a.id);return res.json({status:'provider_required',message:'Secure payment will be enabled after the hospital connects its approved payment provider.'});} res.json({status:'redirect_required',paymentUrl:process.env.HOSPITAL_PAYMENT_WEBHOOK}); });
router.post('/public/portal/:code/cancel', (req,res) => { const a=appointmentRowByBooking(req.params.code); if(!a||!portalAccess(req,a))return res.status(401).json({error:'Verify your booking to continue.'}); if(!['confirmed','waitlisted'].includes(a.status))return res.status(409).json({error:'This appointment can no longer be cancelled online.'}); const reason=String(req.body?.reason||'Patient requested').slice(0,300),now=Date.now(); db.prepare("UPDATE hospital_appointments SET status='cancelled',cancellation_reason=?,cancelled_at=?,updated_at=? WHERE id=?").run(reason,now,now,a.id); if(a.status==='confirmed'&&a.slot_id){db.prepare('UPDATE hospital_slots SET reserved=MAX(reserved-1,0) WHERE id=?').run(a.slot_id);promoteWaitlist(a.slot_id);} event(a.id,'cancelled',a.status,'cancelled','patient',reason);notify(a.id,'cancellation','Your booking was cancelled.');res.json(portalBundle(appointmentRow(a.id))); });
router.post('/public/portal/:code/reschedule', (req,res) => { const a=appointmentRowByBooking(req.params.code); if(!a||!portalAccess(req,a))return res.status(401).json({error:'Verify your booking to continue.'}); const doctorId=Number(req.body?.doctorId),slotId=Number(req.body?.slotId);if(a.status!=='confirmed'||!doctorId||!slotId)return res.status(400).json({error:'A confirmed appointment, doctor and slot are required.'});try{const updated=db.transaction(()=>{const slot=db.prepare('SELECT * FROM hospital_slots WHERE id=? AND doctor_id=?').get(slotId,doctorId);if(!slot||slot.reserved>=slot.capacity)throw new Error('Selected slot is not available.');db.prepare('UPDATE hospital_slots SET reserved=MAX(reserved-1,0) WHERE id=?').run(a.slot_id);db.prepare('UPDATE hospital_slots SET reserved=reserved+1 WHERE id=?').run(slotId);db.prepare('UPDATE hospital_appointments SET doctor_id=?,slot_id=?,updated_at=? WHERE id=?').run(doctorId,slotId,Date.now(),a.id);event(a.id,'rescheduled','confirmed','confirmed','patient');notify(a.id,'rescheduled','Your appointment time was updated.');promoteWaitlist(a.slot_id);return appointmentRow(a.id);})();res.json(portalBundle(updated));}catch(error){res.status(409).json({error:error.message});} });
router.post('/public/walk-ins', (req,res) => {
  const b = req.body || {}, doctorId = Number(b.doctorId), patientName = String(b.patientName || '').trim().slice(0,100); if (!patientName || !doctorId || !db.prepare('SELECT id FROM hospital_doctors WHERE id=? AND active=1').get(doctorId)) return res.status(400).json({error:'Patient name and active doctor are required.'});
  const now = Date.now(), id = db.prepare("INSERT INTO hospital_appointments (booking_code,checkin_code,patient_name,phone,email,doctor_id,reason,status,visit_type,language,checked_in_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)").run(code('WALK'),code('CHK'),patientName,String(b.phone || '').slice(0,40),'',doctorId,String(b.reason || '').slice(0,500),'checked_in','walk_in',String(b.language || 'en').slice(0,10),now,now,now).lastInsertRowid;
  event(id,'walk_in',null,'checked_in','kiosk'); recomputeQueue(doctorId,isoDate(now)); const a = appointmentRow(id); notify(id,'queue_token',`You are checked in. Queue number ${a.queue_number}; estimated wait ${a.estimated_wait_min} minutes.`); res.status(201).json({appointment:publicAppointment(a)});
});
router.get('/public/display', (req,res) => { const doctorId = Number(req.query.doctorId), date = String(req.query.date || isoDate(Date.now())); if (!doctorId) return res.status(400).json({error:'doctorId required'}); recomputeQueue(doctorId,date); const start = dateStart(date), doctor = db.prepare('SELECT name,specialty,location,room FROM hospital_doctors WHERE id=?').get(doctorId); if (!doctor) return res.status(404).json({error:'Doctor not found.'}); const queue = db.prepare("SELECT queue_number,status,estimated_wait_min,visit_type FROM hospital_appointments WHERE doctor_id=? AND checked_in_at>=? AND checked_in_at<? AND status IN ('checked_in','called') ORDER BY queue_number").all(doctorId,start,start+DAY); res.json({doctor,queue,updatedAt:Date.now()}); });
router.post('/public/bookings/:code/check-in', (req,res) => { const a = db.prepare('SELECT * FROM hospital_appointments WHERE checkin_code=?').get(req.params.code); if (!a) return res.status(404).json({error:'Check-in code not found.'}); if (a.status !== 'confirmed') return res.status(409).json({error:`This booking cannot check in (${a.status}).`}); const now = Date.now(); db.prepare("UPDATE hospital_appointments SET status='checked_in',checked_in_at=?,updated_at=? WHERE id=?").run(now,now,a.id); ensureVisitStages(a.id); db.prepare("UPDATE hospital_visit_stages SET status='completed',completed_at=?,updated_at=? WHERE appointment_id=? AND stage='registration'").run(now,now,a.id); event(a.id,'checked_in','confirmed','checked_in','patient'); recomputeQueue(a.doctor_id,isoDate(now)); const updated = appointmentRow(a.id); notify(a.id,'queue_token',`Queue number ${updated.queue_number}; estimated wait ${updated.estimated_wait_min} minutes.`); res.json({appointment:publicAppointment(updated)}); });
router.post('/public/bookings/:code/cancel', (req,res) => { const a = appointmentRowByBooking(req.params.code); if (!a || !portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); res.status(410).json({error:'Use the secure patient portal cancellation workflow.'}); });
router.post('/public/bookings/:code/reschedule', (req,res) => { const a = appointmentRowByBooking(req.params.code); if (!a || !portalAccess(req,a)) return res.status(401).json({error:'Verify your booking to continue.'}); res.status(410).json({error:'Use the secure patient portal rescheduling workflow.'}); });
router.post('/demo', (req,res) => { const text = String(req.body?.text || '').trim().slice(0,500); if (!text) return res.status(400).json({error:'Please describe the patient request.'}); const locale = detectLocale(text), L = I18N[locale] || I18N.en, p = understand(text); res.json({demo:true,locale,steps:[{tool:'demo_intake',result:`(${L.think}) ${p.name || 'Demo patient'}`},{tool:'simulated_token',result:`${L.joined} · demo token #A-104`},{tool:'estimated_wait',result:`3 ${locale === 'hi' ? 'मिनट' : locale === 'ja' ? '分' : 'min'} ${L.eta}`}]}); });

