router.post('/appointments/:id/triage', requirePerm('hospital:manage'), (req,res) => { const a = db.prepare('SELECT * FROM hospital_appointments WHERE id=?').get(req.params.id), b = req.body || {}, disposition = String(b.disposition || ''), flags = Array.isArray(b.redFlags) ? b.redFlags.filter(flag => TRIAGE_FLAGS.includes(flag)) : [], notes = String(b.notes || '').trim().slice(0,1000); if (!a || !['standard','nurse_review','emergency_escalation'].includes(disposition) || (flags.length && disposition === 'standard') || (disposition === 'emergency_escalation' && !notes)) return res.status(400).json({error:'Appointment and a valid nurse disposition are required. Red flags require nurse review or emergency escalation; escalation also requires a note.'}); const now = Date.now(); const id = db.prepare('INSERT INTO hospital_triage_assessments (appointment_id,disposition,red_flags,notes,nurse,created_at) VALUES (?,?,?,?,?,?)').run(a.id,disposition,JSON.stringify(flags),notes,actor(req),now).lastInsertRowid; db.prepare('UPDATE hospital_appointments SET triage_status=?,updated_at=? WHERE id=?').run(disposition,now,a.id); event(a.id,'triage_assessed',a.triage_status,disposition,actor(req),flags.join(',') || notes); if (disposition === 'emergency_escalation') notify(a.id,'emergency_escalation','Your case has been escalated to the clinical team. Please follow staff instructions.'); res.status(201).json({assessment:db.prepare('SELECT * FROM hospital_triage_assessments WHERE id=?').get(id)}); });
