router.post('/appointments/:id/visit-stages/:stage', requirePerm('hospital:manage'), (req,res) => { const appointmentId = Number(req.params.id), stage = req.params.stage, action = req.body?.action, row = visitStages(appointmentId).find(item => item.stage === stage); if (!row || !['start','complete','require','skip'].includes(action)) return res.status(400).json({error:'Valid stage and action are required.'}); const now = Date.now(); if (action === 'require') db.prepare("UPDATE hospital_visit_stages SET status='waiting',updated_at=? WHERE id=?").run(now,row.id); else if (action === 'start') db.prepare("UPDATE hospital_visit_stages SET status='in_progress',started_at=COALESCE(started_at,?),updated_at=? WHERE id=?").run(now,now,row.id); else db.prepare('UPDATE hospital_visit_stages SET status=?,completed_at=?,updated_at=? WHERE id=?').run(action === 'complete' ? 'completed' : 'skipped',now,now,row.id); event(appointmentId,`stage_${action}`,row.status,action,actor(req),stage); res.json({stages:visitStages(appointmentId)}); });
