router.delete('/schedule-blocks/:id', requirePerm('hospital:manage'), (req,res) => { const block = db.prepare('SELECT * FROM hospital_schedule_blocks WHERE id=?').get(req.params.id); if (!block) return res.status(404).json({error:'Schedule block not found.'}); db.prepare('DELETE FROM hospital_schedule_blocks WHERE id=?').run(block.id); db.prepare("UPDATE hospital_slots SET status='open' WHERE doctor_id=? AND starts_at<? AND ends_at>? AND reserved<capacity").run(block.doctor_id,block.ends_at,block.starts_at); res.json({ok:true}); });
router.get('/appointments', requirePerm('hospital:manage'), (req,res) => { const date = String(req.query.date || isoDate(Date.now())), doctorId = Number(req.query.doctorId || 0), start = dateStart(date); res.json(db.prepare("SELECT a.*,d.name doctor_name,d.specialty,s.starts_at FROM hospital_appointments a JOIN hospital_doctors d ON d.id=a.doctor_id LEFT JOIN hospital_slots s ON s.id=a.slot_id WHERE (?=0 OR a.doctor_id=?) AND ((s.starts_at>=? AND s.starts_at<?) OR date(a.created_at/1000,'unixepoch')=?) ORDER BY s.starts_at,a.created_at").all(doctorId,doctorId,start,start+DAY,date)); });
router.get('/queue', requirePerm('hospital:manage'), (req,res) => { const doctorId = Number(req.query.doctorId), date = String(req.query.date || isoDate(Date.now())); if (!doctorId) return res.status(400).json({error:'doctorId required'}); recomputeQueue(doctorId,date); const start = dateStart(date); res.json(db.prepare("SELECT a.*,d.name doctor_name FROM hospital_appointments a JOIN hospital_doctors d ON d.id=a.doctor_id WHERE a.doctor_id=? AND a.checked_in_at>=? AND a.checked_in_at<? AND a.status IN ('checked_in','called') ORDER BY a.queue_number").all(doctorId,start,start+DAY)); });
router.get('/metrics', requirePerm('hospital:manage'), (req,res) => { const date = String(req.query.date || isoDate(Date.now())), start = dateStart(date), end = start + DAY, count = status => db.prepare('SELECT COUNT(*) c FROM hospital_appointments WHERE created_at>=? AND created_at<? AND status=?').get(start,end,status).c, wait = db.prepare("SELECT AVG(CASE WHEN called_at IS NOT NULL THEN (called_at-checked_in_at)/60000 ELSE estimated_wait_min END) avg FROM hospital_appointments WHERE checked_in_at>=? AND checked_in_at<?").get(start,end).avg || 0, service = db.prepare("SELECT AVG((completed_at-called_at)/60000) avg FROM hospital_appointments WHERE completed_at>=? AND completed_at<? AND called_at IS NOT NULL").get(start,end).avg || 0, total = db.prepare('SELECT COUNT(*) c FROM hospital_appointments WHERE created_at>=? AND created_at<?').get(start,end).c; res.json({total,booked:count('confirmed'),checkedIn:count('checked_in'),called:count('called'),completed:count('completed'),cancelled:count('cancelled'),noShow:count('no_show'),waitlisted:count('waitlisted'),averageWaitMin:Math.round(wait),averageServiceMin:Math.round(service),noShowRate: total ? Math.round(count('no_show') * 100 / total) : 0}); });
router.get('/notifications', requirePerm('hospital:manage'), (req,res) => { const id = Number(req.query.appointmentId || 0); res.json(db.prepare('SELECT n.*,a.patient_name FROM hospital_notifications n JOIN hospital_appointments a ON a.id=n.appointment_id WHERE (?=0 OR n.appointment_id=?) ORDER BY n.created_at DESC LIMIT 100').all(id,id)); });
router.post('/appointments/:id/check-in', requirePerm('hospital:manage'), (req,res) => { const a = db.prepare('SELECT * FROM hospital_appointments WHERE id=?').get(req.params.id); if (!a || a.status !== 'confirmed') return res.status(409).json({error:'Only confirmed appointments can check in.'}); const now = Date.now(); db.prepare("UPDATE hospital_appointments SET status='checked_in',checked_in_at=?,updated_at=? WHERE id=?").run(now,now,a.id); ensureVisitStages(a.id); db.prepare("UPDATE hospital_visit_stages SET status='completed',completed_at=?,updated_at=? WHERE appointment_id=? AND stage='registration'").run(now,now,a.id); event(a.id,'checked_in','confirmed','checked_in',actor(req)); recomputeQueue(a.doctor_id,isoDate(now)); res.json({appointment:appointmentRow(a.id)}); });
router.post('/queue/:id/:action', requirePerm('hospital:manage'), (req,res,next) => { const a = db.prepare('SELECT * FROM hospital_appointments WHERE id=?').get(req.params.id), action = req.params.action, transitions = {call:['checked_in','called'],complete:['called','completed'],skip:['checked_in','no_show']}; if (action === 'transfer') return next(); if (!a) return res.status(404).json({error:'Appointment not found.'}); if (!transitions[action] || a.status !== transitions[action][0]) return res.status(409).json({error:`Cannot ${action} this appointment.`}); const now = Date.now(), to = transitions[action][1], field = action === 'call' ? 'called_at' : action === 'complete' ? 'completed_at' : null; db.prepare(`UPDATE hospital_appointments SET status=?,${field ? `${field}=?,` : ''}updated_at=? WHERE id=?`).run(to,...(field ? [now] : []),now,a.id); event(a.id,action,a.status,to,actor(req)); notify(a.id,action === 'call' ? 'turn_alert':action,action === 'call' ? 'It is your turn. Please proceed to the consultation room.':`Appointment ${action}.`); recomputeQueue(a.doctor_id,isoDate(now)); res.json({appointment:appointmentRow(a.id)}); });
router.post('/queue/:id/transfer', requirePerm('hospital:manage'), (req,res) => { const a = db.prepare("SELECT * FROM hospital_appointments WHERE id=? AND status='checked_in'").get(req.params.id), doctorId = Number(req.body?.doctorId); if (!a || !doctorId || !db.prepare('SELECT id FROM hospital_doctors WHERE id=?').get(doctorId)) return res.status(400).json({error:'Checked-in appointment and destination doctor are required.'}); const now = Date.now(); db.prepare('UPDATE hospital_appointments SET doctor_id=?,updated_at=? WHERE id=?').run(doctorId,now,a.id); event(a.id,'transferred','checked_in','checked_in',actor(req),`Transferred to doctor ${doctorId}`); recomputeQueue(a.doctor_id,isoDate(now)); recomputeQueue(doctorId,isoDate(now)); notify(a.id,'transfer','Your consultation queue was transferred.'); res.json({appointment:appointmentRow(a.id)}); });
router.post('/appointments/:id/priority', requirePerm('hospital:manage'), (req,res) => { const a = db.prepare('SELECT * FROM hospital_appointments WHERE id=?').get(req.params.id), priority = req.body?.priority, reason = String(req.body?.reason || '').trim().slice(0,300); if (!a || !['normal','urgent'].includes(priority) || !reason) return res.status(400).json({error:'Appointment, valid priority, and reason are required.'}); db.prepare('UPDATE hospital_appointments SET priority=?,priority_reason=?,updated_at=? WHERE id=?').run(priority,reason,Date.now(),a.id); event(a.id,'priority_changed',a.priority,priority,actor(req),reason); recomputeQueue(a.doctor_id,isoDate(Date.now())); res.json({appointment:appointmentRow(a.id)}); });
router.get('/appointments/:id/history', requirePerm('hospital:manage'), (req,res) => res.json({events:db.prepare('SELECT * FROM hospital_queue_events WHERE appointment_id=? ORDER BY created_at DESC').all(req.params.id),notifications:db.prepare('SELECT * FROM hospital_notifications WHERE appointment_id=? ORDER BY created_at DESC').all(req.params.id)}));

export default router;
